// Case-study videos come with a first-frame poster next to them (intro.mp4 -> intro.poster.webp),
// generated by `npm run posters`. An explicit `poster` on the media still wins.

const VIDEO = /\.(mp4|webm)$/i

export const isVideo = (src) => VIDEO.test(src ?? '')

export const videoPoster = (media) => media.poster ?? media.src.replace(VIDEO, '.poster.webp')
